# Look at EGFR as a well-known internalizing receptor - full JSON
curl -s "https://rest.uniprot.org/uniprotkb/P00533?format=json" 2>/dev/null | python3 -c "
import json, sys
data = json.load(sys.stdin)

print('=== SUBCELLULAR LOCATION ===')
for c in data.get('comments', []):
    if c.get('commentType') == 'SUBCELLULAR LOCATION':
        print(json.dumps(c, indent=2))

print()
print('=== KEYWORDS (filtering relevant) ===')
for kw in data.get('keywords', []):
    name = kw.get('name','').lower()
    if any(t in name for t in ['endocyt', 'endosome', 'lysosome', 'membrane', 'receptor', 'internal', 'transport', 'vesicle', 'clathrin', 'cell surface']):
        print(f\"  {kw['id']}: {kw['name']} (category: {kw.get('category')})\")

print()
print('=== GO TERMS (filtering relevant) ===')
for xref in data.get('uniProtKBCrossReferences', []):
    if xref.get('database') == 'GO':
        term = ''
        for p in xref.get('properties', []):
            if p['key'] == 'GoTerm':
                term = p['value']
        if any(t in term.lower() for t in ['endocyt', 'endosome', 'lysosome', 'internal', 'clathrin', 'vesicle', 'membrane', 'receptor', 'cell surface']):
            print(f\"  {xref['id']}: {term}\")

print()
print('=== FEATURES (filtering for motif, signal, topology) ===')
for feat in data.get('features', []):
    ftype = feat.get('type', '')
    if ftype in ['Motif', 'Signal peptide', 'Topological domain', 'Transmembrane', 'Intramembrane']:
        desc = feat.get('description', '')
        loc = feat.get('location', {})
        start = loc.get('start', {}).get('value', '?')
        end = loc.get('end', {}).get('value', '?')
        print(f\"  {ftype}: {desc} [{start}-{end}]\")
" 2>/dev/null

